
-- Question1
--How many active customers does the platform currently have, by country?
SELECT
    c.country,
    COUNT(DISTINCT c.customer_id) AS active_customer_count
FROM customers c
JOIN subscriptions s
    ON c.customer_id = s.customer_id
WHERE s.subscription_status = 'Active'
GROUP BY c.country
ORDER BY active_customer_count DESC;

--Question 2: What is the total and average monthly revenue generated by each subscription plan?
SELECT
    sp.plan_name,
    SUM(s.monthly_price) AS total_monthly_revenue,
    ROUND(AVG(s.monthly_price), 2) AS average_monthly_revenue
FROM subscriptions s
JOIN subscription_plans sp
    ON s.plan_id = sp.plan_id
WHERE s.subscription_status = 'Active'
GROUP BY sp.plan_name
ORDER BY total_monthly_revenue DESC;

--What is the overall churn rate (percentage of customers with churned = true)?
SELECT
    COUNT(*) FILTER (WHERE churned = TRUE) AS churned_customers,
    COUNT(*) AS total_customers,
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE churned = TRUE) / COUNT(*),
        2
    ) AS overall_churn_rate
FROM churn_labels;

--	Question4-Which acquisition channel has brought in the most customers, and what is the churn rate for each channel?
SELECT
    c.acquisition_channel,
    COUNT(DISTINCT c.customer_id) AS total_customers,
    COUNT(DISTINCT CASE
        WHEN cl.churned = TRUE THEN c.customer_id
    END) AS churned_customers,
    ROUND(
        100.0 * COUNT(DISTINCT CASE
            WHEN cl.churned = TRUE THEN c.customer_id
        END) / COUNT(DISTINCT c.customer_id),
        2
    ) AS churn_rate_percentage
FROM customers c
LEFT JOIN churn_labels cl
    ON c.customer_id = cl.customer_id
GROUP BY c.acquisition_channel
ORDER BY total_customers DESC;

-- Question 5: Calculate average customer age by subscription plan

SELECT
    sp.plan_name,
    ROUND(AVG(c.age), 2) AS average_customer_age

FROM customers c

INNER JOIN subscriptions s
    ON c.customer_id = s.customer_id

INNER JOIN subscription_plans sp
    ON s.plan_id = sp.plan_id

GROUP BY
    sp.plan_name

ORDER BY
    average_customer_age;

---- Question 6: Find the top 10 most-watched titles

SELECT
    c.title,
    SUM(va.watch_duration_minutes) AS total_watch_duration_minutes

FROM viewing_activity va

INNER JOIN content c
    ON va.content_id = c.content_id

GROUP BY
    c.content_id,
    c.title

ORDER BY
    total_watch_duration_minutes DESC

LIMIT 10;

-- Question 7: Average completion percentage by content type and genre

SELECT
    c.content_type,
    c.genre,
    ROUND(AVG(va.completion_percentage), 2) AS average_completion_percentage

FROM viewing_activity va

INNER JOIN content c
    ON va.content_id = c.content_id

GROUP BY
    c.content_type,
    c.genre

ORDER BY
    average_completion_percentage DESC;

---- Question 8: Count failed payments in each of the last 12 months

SELECT
    DATE_TRUNC('month', payment_date)::DATE AS payment_month,
    COUNT(payment_id) AS failed_payment_count

FROM payments

WHERE LOWER(payment_status) = 'failed'
    AND payment_date >= DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '11 months'
    AND payment_date < DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month'

GROUP BY
    DATE_TRUNC('month', payment_date)

ORDER BY
    payment_month

-- Question 9: Find the average resolution time for each issue category

SELECT
    issue_category,
    AVG(resolution_time_hours) AS average_resolution_time_hours

FROM support_tickets

GROUP BY
    issue_category

ORDER BY
    average_resolution_time_hours DESC;	

-- Question 10: What is the distribution of customer_satisfaction_score across all resolved/closed support tickets?

SELECT
    customer_satisfaction_score,
    COUNT(*) AS ticket_count,
    ROUND(
        COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (),
        2
    ) AS percentage
FROM support_tickets
WHERE LOWER(ticket_status) IN ('resolved', 'closed')
  AND customer_satisfaction_score IS NOT NULL
GROUP BY customer_satisfaction_score
ORDER BY customer_satisfaction_score;

-- Question 11: Which device_type generates the most total viewing minutes?

SELECT
    LOWER(TRIM(device_type)) AS device_type,
    SUM(watch_duration_minutes) AS total_viewing_minutes

FROM viewing_activity

WHERE device_type IS NOT NULL

GROUP BY LOWER(TRIM(device_type))

ORDER BY total_viewing_minutes DESC;

-- Question 12: What is the average rating from customer_feedback, grouped by sentiment_label?

SELECT
    sentiment_label,
    ROUND(AVG(rating), 2) AS average_rating

FROM customer_feedback

WHERE rating IS NOT NULL
  AND sentiment_label IS NOT NULL

GROUP BY sentiment_label

ORDER BY average_rating DESC;

-- Question 13: How many customers signed up through each acquisition_channel in each calendar year?

SELECT
    EXTRACT(YEAR FROM registration_date)::INT AS signup_year,
    acquisition_channel,
    COUNT(DISTINCT customer_id) AS customer_count

FROM customers

WHERE registration_date IS NOT NULL

GROUP BY
    EXTRACT(YEAR FROM registration_date),
    acquisition_channel

ORDER BY
    signup_year,
    customer_count DESC;

-- Question 14: What percentage of customers have auto_renew turned off?

SELECT
    ROUND(
        COUNT(DISTINCT customer_id) FILTER (
            WHERE auto_renew = FALSE
        ) * 100.0 /
        NULLIF(
            COUNT(DISTINCT customer_id) FILTER (
                WHERE auto_renew IS NOT NULL
            ), 0
        ),
        2
    ) AS percentage_auto_renew_off

FROM subscriptions

WHERE LOWER(TRIM(subscription_status)) = 'active';

-- Question 15: List all customers who have raised more than 3 support tickets,
-- along with their total ticket count.

SELECT
    c.customer_id,
    c.first_name,
    c.last_name,
    COUNT(st.ticket_id) AS total_ticket_count

FROM customers c

JOIN support_tickets st
    ON c.customer_id = st.customer_id

GROUP BY
    c.customer_id,
    c.first_name,
    c.last_name

HAVING COUNT(st.ticket_id) > 3

ORDER BY total_ticket_count DESC;

--Advanced
-- Question 16: Using RANK(), rank subscription plans by total revenue generated
-- (monthly_price × count of active subscriptions).

WITH plan_revenue AS (
    SELECT
        p.plan_id,
        p.plan_name,
        p.monthly_price,
        COUNT(s.subscription_id) AS active_subscription_count,

        p.monthly_price * COUNT(s.subscription_id)
            AS total_monthly_revenue

    FROM subscription_plans p

    LEFT JOIN subscriptions s
        ON p.plan_id = s.plan_id
        AND LOWER(TRIM(s.subscription_status)) = 'active'

    GROUP BY
        p.plan_id,
        p.plan_name,
        p.monthly_price
)

SELECT
    plan_id,
    plan_name,
    monthly_price,
    active_subscription_count,
    total_monthly_revenue,

    RANK() OVER (
        ORDER BY total_monthly_revenue DESC
    ) AS revenue_rank

FROM plan_revenue

ORDER BY revenue_rank;

-- Question 17: For each customer, use ROW_NUMBER() to identify their most recent support ticket and return only that row.

WITH ranked_tickets AS (
    SELECT
        st.*,
        ROW_NUMBER() OVER (
            PARTITION BY st.customer_id
            ORDER BY st.ticket_date DESC NULLS LAST,
                     st.ticket_id DESC
        ) AS rn
    FROM support_tickets AS st
)

SELECT
    customer_id,
    ticket_id,
    ticket_date,
    issue_category,
    issue_subcategory,
    priority,
    ticket_status,
    resolution_time_hours,
    customer_satisfaction_score,
    ticket_description,
    support_agent_id
FROM ranked_tickets
WHERE rn = 1
ORDER BY customer_id;

-- Question 18: Calculate a 3-month moving average of new customer registrations using a window function.

WITH monthly_registrations AS (
    SELECT
        DATE_TRUNC('month', registration_date)::DATE AS registration_month,
        COUNT(DISTINCT customer_id) AS new_customers
    FROM customers
    WHERE registration_date IS NOT NULL
    GROUP BY DATE_TRUNC('month', registration_date)
)

SELECT
    registration_month,
    new_customers,
    ROUND(
        AVG(new_customers) OVER (
            ORDER BY registration_month
            ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
        ), 2
    ) AS moving_average_3_months
FROM monthly_registrations
ORDER BY registration_month;

-- Question 19: Using LAG(), identify customers whose monthly watch time in the most recent month is lower than their watch time in the prior month (a month-over-month decline flag).

WITH monthly_watch_time AS (
    SELECT
        customer_id,
        DATE_TRUNC('month', viewing_date)::DATE AS viewing_month,
        SUM(watch_duration_minutes) AS monthly_watch_minutes
    FROM viewing_activity
    GROUP BY
        customer_id,
        DATE_TRUNC('month', viewing_date)
),

watch_time_comparison AS (
    SELECT
        customer_id,
        viewing_month,
        monthly_watch_minutes,
        LAG(monthly_watch_minutes) OVER (
            PARTITION BY customer_id
            ORDER BY viewing_month
        ) AS previous_month_watch_minutes
    FROM monthly_watch_time
),

ranked_customers AS (
    SELECT
        *,
        ROW_NUMBER() OVER (
            PARTITION BY customer_id
            ORDER BY viewing_month DESC
        ) AS rn
    FROM watch_time_comparison
)

SELECT
    customer_id,
    viewing_month AS most_recent_month,
    monthly_watch_minutes AS current_month_watch_time,
    previous_month_watch_minutes,
    TRUE AS decline_flag
FROM ranked_customers
WHERE rn = 1
    AND previous_month_watch_minutes IS NOT NULL
    AND monthly_watch_minutes < previous_month_watch_minutes
ORDER BY customer_id;

-- Question 20: Build a customer acquisition cohort analysis: group customers by the month they registered, and show what percentage of each cohort is still active at 1, 3, and 6 months after registration.

SELECT
    DATE_TRUNC('month', c.registration_date)::DATE AS cohort_month,

    COUNT(*) AS cohort_size,

    ROUND(
        100.0 * COUNT(*) FILTER (
            WHERE COALESCE(cl.churned, FALSE) = FALSE
               OR cl.churn_date > c.registration_date + INTERVAL '1 month'
        ) / COUNT(*), 2
    ) AS retention_1_month_pct,

    ROUND(
        100.0 * COUNT(*) FILTER (
            WHERE COALESCE(cl.churned, FALSE) = FALSE
               OR cl.churn_date > c.registration_date + INTERVAL '3 months'
        ) / COUNT(*), 2
    ) AS retention_3_months_pct,

    ROUND(
        100.0 * COUNT(*) FILTER (
            WHERE COALESCE(cl.churned, FALSE) = FALSE
               OR cl.churn_date > c.registration_date + INTERVAL '6 months'
        ) / COUNT(*), 2
    ) AS retention_6_months_pct

FROM customers AS c
LEFT JOIN churn_labels AS cl
    ON c.customer_id = cl.customer_id

WHERE c.registration_date IS NOT NULL

GROUP BY DATE_TRUNC('month', c.registration_date)

ORDER BY cohort_month;

-- Question 22: For every customer, compute a running total of payments made, ordered by payment_date, using a window function.

SELECT
    customer_id,
    payment_id,
    payment_date,
    amount,
    payment_status,
    SUM(amount) OVER (
        PARTITION BY customer_id
        ORDER BY payment_date, payment_id
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS running_total_payments
FROM payments
ORDER BY customer_id, payment_date, payment_id;

-- Question 23: Identify customers whose watch time declined for three consecutive months (month N < month N-1 < month N-2).

WITH monthly_watch_time AS (
    SELECT
        customer_id,
        DATE_TRUNC('month', viewing_date)::date AS watch_month,
        SUM(watch_duration_minutes) AS monthly_watch_minutes
    FROM viewing_activity
    WHERE viewing_date IS NOT NULL
    GROUP BY
        customer_id,
        DATE_TRUNC('month', viewing_date)
),

watch_time_trends AS (
    SELECT
        customer_id,
        watch_month,
        monthly_watch_minutes,

        LAG(watch_month, 1) OVER (
            PARTITION BY customer_id
            ORDER BY watch_month
        ) AS previous_month,

        LAG(monthly_watch_minutes, 1) OVER (
            PARTITION BY customer_id
            ORDER BY watch_month
        ) AS previous_month_watch_time,

        LAG(watch_month, 2) OVER (
            PARTITION BY customer_id
            ORDER BY watch_month
        ) AS two_months_ago,

        LAG(monthly_watch_minutes, 2) OVER (
            PARTITION BY customer_id
            ORDER BY watch_month
        ) AS two_months_ago_watch_time

    FROM monthly_watch_time
)

SELECT
    customer_id,
    watch_month,
    monthly_watch_minutes,
    previous_month_watch_time,
    two_months_ago_watch_time
FROM watch_time_trends
WHERE
    watch_month = (previous_month + INTERVAL '1 month')::date
    AND previous_month = (two_months_ago + INTERVAL '1 month')::date
    AND monthly_watch_minutes < previous_month_watch_time
    AND previous_month_watch_time < two_months_ago_watch_time
ORDER BY customer_id, watch_month;

-- Question 24: Calculate the monthly churn rate over the last 12 months (churned customers in month X / active customers at start of month X).

WITH date_range AS (
    SELECT
        DATE_TRUNC('month', MAX(churn_date))::date AS latest_month
    FROM churn_labels
    WHERE churned = TRUE
      AND churn_date IS NOT NULL
),

months AS (
    SELECT
        GENERATE_SERIES(
            latest_month - INTERVAL '11 months',
            latest_month,
            INTERVAL '1 month'
        )::date AS churn_month
    FROM date_range
),

monthly_churn AS (
    SELECT
        DATE_TRUNC('month', churn_date)::date AS churn_month,
        COUNT(DISTINCT customer_id) AS churned_customers
    FROM churn_labels
    WHERE churned = TRUE
      AND churn_date IS NOT NULL
    GROUP BY DATE_TRUNC('month', churn_date)
),

active_customers AS (
    SELECT
        m.churn_month,
        COUNT(DISTINCT c.customer_id) AS active_at_start
    FROM months AS m
    JOIN customers AS c
        ON c.registration_date < m.churn_month
    LEFT JOIN churn_labels AS cl
        ON c.customer_id = cl.customer_id
    WHERE
        cl.customer_id IS NULL
        OR cl.churned = FALSE
        OR cl.churn_date >= m.churn_month
    GROUP BY m.churn_month
)

SELECT
    m.churn_month,
    ac.active_at_start,
    COALESCE(mc.churned_customers, 0) AS churned_customers,
    ROUND(
        100.0 * COALESCE(mc.churned_customers, 0)
        / NULLIF(ac.active_at_start, 0),
        2
    ) AS monthly_churn_rate_pct
FROM months AS m
JOIN active_customers AS ac
    ON m.churn_month = ac.churn_month
LEFT JOIN monthly_churn AS mc
    ON m.churn_month = mc.churn_month
ORDER BY m.churn_month;

-- Question 25: Calculate customer retention rate by acquisition_channel: of the customers acquired through each channel, what percentage are still active today?

SELECT
    c.acquisition_channel,
    COUNT(DISTINCT c.customer_id) AS total_customers,
    COUNT(DISTINCT CASE
        WHEN cl.churned = FALSE THEN c.customer_id
    END) AS active_customers,
    ROUND(
        100.0 * COUNT(DISTINCT CASE
            WHEN cl.churned = FALSE THEN c.customer_id
        END) / NULLIF(COUNT(DISTINCT c.customer_id), 0),
        2
    ) AS retention_rate_pct
FROM customers AS c
LEFT JOIN churn_labels AS cl
    ON c.customer_id = cl.customer_id
GROUP BY c.acquisition_channel
ORDER BY retention_rate_pct DESC;

-- Question 26: Using a CTE, compute each customer's total lifetime spend (sum of successful payments) and rank customers into quartiles using NTILE(4).

WITH customer_lifetime_spend AS (
    SELECT
        c.customer_id,
        COALESCE(SUM(p.amount), 0) AS total_lifetime_spend
    FROM customers AS c
    LEFT JOIN payments AS p
        ON c.customer_id = p.customer_id
        AND p.payment_status = 'Success'
    GROUP BY c.customer_id
)

SELECT
    customer_id,
    total_lifetime_spend,
    NTILE(4) OVER (
        ORDER BY total_lifetime_spend DESC, customer_id
    ) AS spend_quartile
FROM customer_lifetime_spend
ORDER BY total_lifetime_spend DESC, customer_id;

-- Question 27: Find the top 3 issue_subcategory values by ticket volume, per country, using a CTE combined with ROW_NUMBER() partitioned by country.

WITH subcategory_ticket_counts AS (
    SELECT
        c.country,
        st.issue_subcategory,
        COUNT(*) AS ticket_volume
    FROM support_tickets AS st
    JOIN customers AS c
        ON st.customer_id = c.customer_id
    WHERE c.country IS NOT NULL
      AND st.issue_subcategory IS NOT NULL
    GROUP BY
        c.country,
        st.issue_subcategory
),

ranked_subcategories AS (
    SELECT
        country,
        issue_subcategory,
        ticket_volume,
        ROW_NUMBER() OVER (
            PARTITION BY country
            ORDER BY ticket_volume DESC, issue_subcategory
        ) AS rn
    FROM subcategory_ticket_counts
)

SELECT
    country,
    issue_subcategory,
    ticket_volume
FROM ranked_subcategories
WHERE rn <= 3
ORDER BY country, rn;

-- Question 28: Identify customers with 2+ failed payments
-- in the last 90 days who are flagged as high churn risk.

WITH latest_payment_date AS (

    -- Get the latest payment date in the dataset
    SELECT
        MAX(payment_date) AS max_payment_date
    FROM payments
),

failed_payment_counts AS (

    -- Count failed payments for each customer in the last 90 days
    SELECT
        p.customer_id,
        COUNT(*) AS failed_payment_count
    FROM payments AS p
    CROSS JOIN latest_payment_date AS ld
    WHERE LOWER(TRIM(p.payment_status)) = 'failed'
      AND p.payment_date >= ld.max_payment_date - INTERVAL '90 days'
      AND p.payment_date <= ld.max_payment_date
    GROUP BY p.customer_id
    HAVING COUNT(*) >= 2
),

latest_subscription AS (

    -- Identify each customer's latest subscription and plan
    SELECT
        s.customer_id,
        sp.plan_name AS current_plan,
        ROW_NUMBER() OVER (
            PARTITION BY s.customer_id
            ORDER BY
                CASE
                    WHEN LOWER(TRIM(s.subscription_status)) = 'active'
                    THEN 1 ELSE 2
                END,
                s.subscription_start_date DESC,
                s.subscription_id DESC
        ) AS rn
    FROM subscriptions AS s
    LEFT JOIN subscription_plans AS sp
        ON s.plan_id = sp.plan_id
)

-- Return the final customer details
SELECT
    f.customer_id,
    f.failed_payment_count,
    ls.current_plan
FROM failed_payment_counts AS f
JOIN churn_labels AS cl
    ON f.customer_id = cl.customer_id
LEFT JOIN latest_subscription AS ls
    ON f.customer_id = ls.customer_id
    AND ls.rn = 1
WHERE cl.churned = TRUE
ORDER BY f.failed_payment_count DESC;

-- QUESTION 29:
-- Compare average customer engagement (avg watch_duration_minutes per session)
-- for the 30 days before and 30 days after each customer's most recent
-- subscription price change. Report the percentage change.

WITH subscription_history AS (

    -- Step 1: Retrieve subscription prices and previous prices
    SELECT
        customer_id,
        subscription_id,
        subscription_start_date,
        monthly_price,

        LAG(monthly_price) OVER (
            PARTITION BY customer_id
            ORDER BY subscription_start_date, subscription_id
        ) AS previous_monthly_price

    FROM subscriptions
    WHERE monthly_price IS NOT NULL
),

price_changes AS (

    -- Step 2: Identify actual price changes
    SELECT
        customer_id,
        subscription_id,
        subscription_start_date AS price_change_date,
        previous_monthly_price,
        monthly_price

    FROM subscription_history

    WHERE previous_monthly_price IS NOT NULL
      AND monthly_price <> previous_monthly_price
),

latest_price_change AS (

    -- Step 3: Find the most recent price change for each customer
    SELECT
        customer_id,
        subscription_id,
        price_change_date

    FROM (
        SELECT
            *,
            ROW_NUMBER() OVER (
                PARTITION BY customer_id
                ORDER BY price_change_date DESC, subscription_id DESC
            ) AS rn

        FROM price_changes
    ) AS ranked

    WHERE rn = 1
),

engagement_comparison AS (

    -- Step 4: Calculate engagement before and after price change
    SELECT
        pc.customer_id,
        pc.price_change_date,

        ROUND(
            AVG(va.watch_duration_minutes) FILTER (
                WHERE va.viewing_date >= pc.price_change_date - INTERVAL '30 days'
                  AND va.viewing_date < pc.price_change_date
            ), 2
        ) AS avg_watch_time_before,

        ROUND(
            AVG(va.watch_duration_minutes) FILTER (
                WHERE va.viewing_date >= pc.price_change_date
                  AND va.viewing_date < pc.price_change_date + INTERVAL '30 days'
            ), 2
        ) AS avg_watch_time_after

    FROM latest_price_change AS pc

    LEFT JOIN viewing_activity AS va
        ON pc.customer_id = va.customer_id
       AND va.viewing_date >= pc.price_change_date - INTERVAL '30 days'
       AND va.viewing_date < pc.price_change_date + INTERVAL '30 days'

    GROUP BY pc.customer_id, pc.price_change_date
)

-- Step 5: Calculate percentage change in engagement
SELECT
    customer_id,
    price_change_date,
    avg_watch_time_before,
    avg_watch_time_after,

    ROUND(
        (
            (avg_watch_time_after - avg_watch_time_before)
            / NULLIF(avg_watch_time_before, 0)
        ) * 100,
        2
    ) AS engagement_percentage_change

FROM engagement_comparison

ORDER BY engagement_percentage_change DESC NULLS LAST;

-- QUESTION 29:
-- Compare average customer engagement for the 30 days before
-- and after each customer's most recent subscription price change.
-- VERIFICATION 1: Check whether historical subscription price changes exist.

WITH subscription_history AS (

    SELECT
        customer_id,
        subscription_id,
        subscription_start_date,
        monthly_price,

        LAG(monthly_price) OVER (
            PARTITION BY customer_id
            ORDER BY subscription_start_date, subscription_id
        ) AS previous_monthly_price

    FROM subscriptions
    WHERE monthly_price IS NOT NULL
)

SELECT
    COUNT(*) AS total_subscription_records,

    COUNT(*) FILTER (
        WHERE previous_monthly_price IS NOT NULL
    ) AS records_with_previous_subscription,

    COUNT(*) FILTER (
        WHERE previous_monthly_price IS NOT NULL
          AND monthly_price <> previous_monthly_price
    ) AS total_price_changes,

    COUNT(DISTINCT customer_id) FILTER (
        WHERE previous_monthly_price IS NOT NULL
          AND monthly_price <> previous_monthly_price
    ) AS customers_with_price_changes

FROM subscription_history;

-- QUESTION 29:
-- Compare average customer engagement (avg watch_duration_minutes per session)
-- for the 30 days before and 30 days after each customer's most recent
-- subscription price change. Report the percentage change.
--
-- VERIFICATION 2: Check whether customers changed subscription plans.

WITH subscription_history AS (
    SELECT
        customer_id,
        subscription_id,
        subscription_start_date,
        plan_id,
        monthly_price,

        LAG(plan_id) OVER (
            PARTITION BY customer_id
            ORDER BY subscription_start_date, subscription_id
        ) AS previous_plan_id,

        LAG(monthly_price) OVER (
            PARTITION BY customer_id
            ORDER BY subscription_start_date, subscription_id
        ) AS previous_price

    FROM subscriptions
)

SELECT
    COUNT(*) FILTER (
        WHERE previous_plan_id IS NOT NULL
    ) AS customers_with_previous_records,

    COUNT(*) FILTER (
        WHERE plan_id <> previous_plan_id
    ) AS total_plan_changes,

    COUNT(DISTINCT customer_id) FILTER (
        WHERE plan_id <> previous_plan_id
    ) AS customers_who_changed_plans,

    COUNT(*) FILTER (
        WHERE monthly_price <> previous_price
    ) AS total_price_changes

FROM subscription_history;

-- Question 29:
-- Compare average customer engagement (avg watch_duration_minutes per session)
-- for the 30 days before and 30 days after each customer's most recent
-- subscription price change. Report the percentage change.

-- Verification: Identify all recorded subscription price changes.

WITH subscription_history AS (
    SELECT
        customer_id,
        subscription_id,
        subscription_start_date,
        monthly_price,

        LAG(monthly_price) OVER (
            PARTITION BY customer_id
            ORDER BY subscription_start_date, subscription_id
        ) AS previous_monthly_price,

        ROW_NUMBER() OVER (
            PARTITION BY customer_id
            ORDER BY subscription_start_date, subscription_id
        ) AS subscription_sequence

    FROM subscriptions
)

SELECT
    customer_id,
    subscription_id,
    subscription_start_date AS price_change_date,
    previous_monthly_price,
    monthly_price AS new_monthly_price

FROM subscription_history

WHERE subscription_sequence > 1
  AND monthly_price IS DISTINCT FROM previous_monthly_price

ORDER BY customer_id, price_change_date;

--No subscription price changes were identified in the dataset. Therefore, the impact of subscription price changes on customer engagement could not be measured.

-- Question 30:
-- For each country, calculate: total customers, churned customers,
-- churn rate, average customer lifetime value
-- (sum of successful payments per churned customer),
-- and top 1 churn_reason — all in a single result set using CTEs.

WITH customer_base AS (

    -- Step 1: Combine customers with their churn information
    SELECT
        c.customer_id,
        COALESCE(NULLIF(TRIM(c.country), ''), 'Unknown') AS country,
        COALESCE(cl.churned, FALSE) AS churned,
        NULLIF(TRIM(cl.churn_reason), '') AS churn_reason

    FROM customers AS c

    LEFT JOIN churn_labels AS cl
        ON c.customer_id = cl.customer_id
),

successful_payment_totals AS (

    -- Step 2: Calculate lifetime successful payments per customer
    SELECT
        customer_id,
        SUM(amount) AS lifetime_value

    FROM payments

    WHERE LOWER(TRIM(payment_status)) = 'success'

    GROUP BY customer_id
),

country_metrics AS (

    -- Step 3: Calculate customer count and churn rate per country
    SELECT
        country,
        COUNT(*) AS total_customers,

        COUNT(*) FILTER (
            WHERE churned = TRUE
        ) AS churned_customers,

        ROUND(
            100.0 * COUNT(*) FILTER (
                WHERE churned = TRUE
            ) / NULLIF(COUNT(*), 0),
            2
        ) AS churn_rate_percentage

    FROM customer_base

    GROUP BY country
),

churned_customer_ltv AS (

    -- Step 4: Calculate lifetime value for each churned customer
    SELECT
        cb.country,
        cb.customer_id,
        COALESCE(spt.lifetime_value, 0) AS lifetime_value

    FROM customer_base AS cb

    LEFT JOIN successful_payment_totals AS spt
        ON cb.customer_id = spt.customer_id

    WHERE cb.churned = TRUE
),

country_ltv AS (

    -- Step 5: Calculate average lifetime value per country
    SELECT
        country,
        ROUND(AVG(lifetime_value), 2)
            AS average_customer_lifetime_value

    FROM churned_customer_ltv

    GROUP BY country
),

churn_reason_counts AS (

    -- Step 6: Count churn reasons per country
    SELECT
        country,
        churn_reason,
        COUNT(*) AS reason_count

    FROM customer_base

    WHERE churned = TRUE
      AND churn_reason IS NOT NULL

    GROUP BY country, churn_reason
),

ranked_churn_reasons AS (

    -- Step 7: Rank churn reasons within each country
    SELECT
        country,
        churn_reason,
        reason_count,

        ROW_NUMBER() OVER (
            PARTITION BY country
            ORDER BY reason_count DESC, churn_reason
        ) AS rn

    FROM churn_reason_counts
)

-- Step 8: Combine all country-level results
SELECT
    cm.country,
    cm.total_customers,
    cm.churned_customers,
    cm.churn_rate_percentage,

    cltv.average_customer_lifetime_value,

    rcr.churn_reason AS top_1_churn_reason

FROM country_metrics AS cm

LEFT JOIN country_ltv AS cltv
    ON cm.country = cltv.country

LEFT JOIN ranked_churn_reasons AS rcr
    ON cm.country = rcr.country
    AND rcr.rn = 1

ORDER BY cm.churn_rate_percentage DESC;


-- Question 31:
-- Build an “at-risk revenue” report: for every currently active customer,
-- estimate churn risk using a composite SQL score (normalized combination of
-- days_since_last_activity, failed_payment_rate, and support_ticket_count)
-- and multiply by monthly_price. Rank the top 50 highest at-risk-revenue customers.

WITH latest_subscription AS (

    -- Step 1: Identify each customer's latest subscription
    SELECT
        s.customer_id,
        s.subscription_id,
        s.plan_id,
        sp.plan_name,
        COALESCE(s.monthly_price, sp.monthly_price) AS monthly_price,
        s.subscription_status,

        ROW_NUMBER() OVER (
            PARTITION BY s.customer_id
            ORDER BY s.subscription_start_date DESC,
                     s.subscription_id DESC
        ) AS rn

    FROM subscriptions AS s

    LEFT JOIN subscription_plans AS sp
        ON s.plan_id = sp.plan_id
),

active_customers AS (

    -- Step 2: Keep only customers with a currently active subscription
    SELECT
        c.customer_id,
        c.registration_date,
        ls.subscription_id,
        ls.plan_name,
        ls.monthly_price

    FROM latest_subscription AS ls

    JOIN customers AS c
        ON ls.customer_id = c.customer_id

    WHERE ls.rn = 1
      AND LOWER(TRIM(ls.subscription_status)) = 'active'
),

viewing_metrics AS (

    -- Step 3: Find each customer's most recent viewing activity
    SELECT
        customer_id,
        MAX(viewing_date) AS last_activity_date

    FROM viewing_activity

    GROUP BY customer_id
),

payment_metrics AS (

    -- Step 4: Calculate failed payment rate for each customer
    SELECT
        customer_id,

        COUNT(*) AS total_payment_count,

        COUNT(*) FILTER (
            WHERE LOWER(TRIM(payment_status)) = 'failed'
        ) AS failed_payment_count

    FROM payments

    GROUP BY customer_id
),

support_metrics AS (

    -- Step 5: Calculate total support tickets per customer
    SELECT
        customer_id,
        COUNT(*) AS support_ticket_count

    FROM support_tickets

    GROUP BY customer_id
),

customer_risk_inputs AS (

    -- Step 6: Combine all three churn risk indicators
    SELECT
        ac.customer_id,
        ac.plan_name,
        ac.monthly_price,

        COALESCE(
            CURRENT_DATE - COALESCE(
                vm.last_activity_date,
                ac.registration_date
            ),
            0
        ) AS days_since_last_activity,

        COALESCE(
            pm.failed_payment_count::NUMERIC
            / NULLIF(pm.total_payment_count, 0),
            0
        ) AS failed_payment_rate,

        COALESCE(
            sm.support_ticket_count,
            0
        ) AS support_ticket_count

    FROM active_customers AS ac

    LEFT JOIN viewing_metrics AS vm
        ON ac.customer_id = vm.customer_id

    LEFT JOIN payment_metrics AS pm
        ON ac.customer_id = pm.customer_id

    LEFT JOIN support_metrics AS sm
        ON ac.customer_id = sm.customer_id
),

normalized_scores AS (

    -- Step 7: Normalize all three indicators using min-max normalization
    SELECT
        *,

        COALESCE(
            (days_since_last_activity -
             MIN(days_since_last_activity) OVER ())::NUMERIC
            /
            NULLIF(
                (MAX(days_since_last_activity) OVER () -
                 MIN(days_since_last_activity) OVER ())::NUMERIC,
                0
            ),
            0
        ) AS normalized_activity_score,

        COALESCE(
            (failed_payment_rate -
             MIN(failed_payment_rate) OVER ())
            /
            NULLIF(
                MAX(failed_payment_rate) OVER () -
                MIN(failed_payment_rate) OVER (),
                0
            ),
            0
        ) AS normalized_payment_score,

        COALESCE(
            (support_ticket_count -
             MIN(support_ticket_count) OVER ())::NUMERIC
            /
            NULLIF(
                (MAX(support_ticket_count) OVER () -
                 MIN(support_ticket_count) OVER ())::NUMERIC,
                0
            ),
            0
        ) AS normalized_support_score

    FROM customer_risk_inputs
),

churn_risk AS (

    -- Step 8: Calculate composite churn risk score (0–100)
    SELECT
        *,

        ROUND(
            100.0 * (
                normalized_activity_score
                + normalized_payment_score
                + normalized_support_score
            ) / 3.0,
            2
        ) AS churn_risk_score

    FROM normalized_scores
),

at_risk_revenue AS (

    -- Step 9: Calculate estimated at-risk monthly revenue
    SELECT
        customer_id,
        plan_name,
        days_since_last_activity,
        failed_payment_rate,
        support_ticket_count,
        churn_risk_score,
        monthly_price,

        ROUND(
            monthly_price * churn_risk_score / 100.0,
            2
        ) AS at_risk_monthly_revenue

    FROM churn_risk
),

ranked_customers AS (

    -- Step 10: Rank customers by at-risk monthly revenue
    SELECT
        *,

        ROW_NUMBER() OVER (
            ORDER BY
                at_risk_monthly_revenue DESC,
                churn_risk_score DESC,
                customer_id
        ) AS revenue_risk_rank

    FROM at_risk_revenue
)

-- Step 11: Return the top 50 highest at-risk-revenue customers
SELECT *
FROM ranked_customers

WHERE revenue_risk_rank <= 50

ORDER BY revenue_risk_rank;

-- Question 32:
-- Identify the top 5 customer complaints (by issue_subcategory) per country
-- for the most recent completed quarter, along with average resolution
-- time and average satisfaction score for that subcategory.

WITH latest_ticket_date AS (
    SELECT
        MAX(ticket_date) AS max_ticket_date
    FROM support_tickets
),

quarter_period AS (
    SELECT
        CASE
            WHEN max_ticket_date =
                (DATE_TRUNC('quarter', max_ticket_date)
                 + INTERVAL '3 months'
                 - INTERVAL '1 day')::date
            THEN DATE_TRUNC('quarter', max_ticket_date)::date
            ELSE (DATE_TRUNC('quarter', max_ticket_date)
                  - INTERVAL '3 months')::date
        END AS quarter_start,

        CASE
            WHEN max_ticket_date =
                (DATE_TRUNC('quarter', max_ticket_date)
                 + INTERVAL '3 months'
                 - INTERVAL '1 day')::date
            THEN (DATE_TRUNC('quarter', max_ticket_date)
                  + INTERVAL '3 months')::date
            ELSE DATE_TRUNC('quarter', max_ticket_date)::date
        END AS quarter_end

    FROM latest_ticket_date
),

complaint_summary AS (
    SELECT
        c.country,
        st.issue_subcategory,
        COUNT(st.ticket_id) AS total_tickets,

        ROUND(AVG(st.resolution_time_hours), 2)
            AS avg_resolution_time_hours,

        ROUND(AVG(st.customer_satisfaction_score), 2)
            AS avg_satisfaction_score

    FROM support_tickets st

    JOIN customers c
        ON st.customer_id = c.customer_id

    CROSS JOIN quarter_period qp

    WHERE st.ticket_date >= qp.quarter_start
      AND st.ticket_date < qp.quarter_end
      AND st.issue_subcategory IS NOT NULL

    GROUP BY
        c.country,
        st.issue_subcategory
),

ranked_complaints AS (
    SELECT
        *,
        ROW_NUMBER() OVER (
            PARTITION BY country
            ORDER BY total_tickets DESC, issue_subcategory
        ) AS complaint_rank

    FROM complaint_summary
)

SELECT
    country,
    issue_subcategory,
    total_tickets,
    avg_resolution_time_hours,
    avg_satisfaction_score,
    complaint_rank

FROM ranked_complaints

WHERE complaint_rank <= 5

ORDER BY
    country,
    complaint_rank;

-- Question 33: Using window functions, identify “win-back” candidates: customers who churned but had a customer_lifetime_value in the top quartile before churning. Return their churn_reason and last known engagement level.

WITH churned_customers AS (
    SELECT
        customer_id,
        churn_date,
        churn_reason
    FROM churn_labels
    WHERE churned = TRUE
      AND churn_date IS NOT NULL
),

customer_lifetime_value AS (
    SELECT
        cc.customer_id,
        cc.churn_date,
        cc.churn_reason,
        COALESCE(SUM(p.amount), 0) AS customer_lifetime_value
    FROM churned_customers cc
    LEFT JOIN payments p
        ON cc.customer_id = p.customer_id
       AND p.payment_status = 'Success'
       AND p.payment_date <= cc.churn_date
    GROUP BY
        cc.customer_id,
        cc.churn_date,
        cc.churn_reason
),

ltv_quartiles AS (
    SELECT
        *,
        NTILE(4) OVER (
            ORDER BY customer_lifetime_value DESC
        ) AS ltv_quartile
    FROM customer_lifetime_value
),

last_known_engagement AS (
    SELECT
        cc.customer_id,
        COALESCE(
            SUM(va.watch_duration_minutes), 0
        ) AS last_30_day_watch_minutes
    FROM churned_customers cc
    LEFT JOIN viewing_activity va
        ON cc.customer_id = va.customer_id
       AND va.viewing_date >= cc.churn_date - INTERVAL '30 days'
       AND va.viewing_date <= cc.churn_date
    GROUP BY cc.customer_id
),

engagement_levels AS (
    SELECT
        customer_id,
        last_30_day_watch_minutes,
        CASE
            WHEN last_30_day_watch_minutes = 0
                THEN 'No recent viewing'
            ELSE
                CASE NTILE(4) OVER (
                    ORDER BY last_30_day_watch_minutes DESC
                )
                    WHEN 1 THEN 'High'
                    WHEN 2 THEN 'Moderate'
                    WHEN 3 THEN 'Low'
                    WHEN 4 THEN 'Very Low'
                END
        END AS last_known_engagement_level
    FROM last_known_engagement
)

SELECT
    l.customer_id,
    l.customer_lifetime_value,
    l.churn_reason,
    e.last_known_engagement_level,
    e.last_30_day_watch_minutes
FROM ltv_quartiles l
JOIN engagement_levels e
    ON l.customer_id = e.customer_id
WHERE l.ltv_quartile = 1
ORDER BY l.customer_lifetime_value DESC;

-- Question 34 Build a plan-migration analysis: for customers who appear more than once in subscriptions (plan changes), identify the most common migration path (e.g., Basic → Standard) and whether upgraders churn at a different rate than downgraders.

WITH subscription_history AS (
    SELECT
        s.customer_id,
        s.subscription_id,
        s.plan_id,
        s.subscription_start_date,
        sp.plan_name,
        sp.monthly_price,

        LAG(s.plan_id) OVER (
            PARTITION BY s.customer_id
            ORDER BY s.subscription_start_date, s.subscription_id
        ) AS previous_plan_id,

        LAG(sp.plan_name) OVER (
            PARTITION BY s.customer_id
            ORDER BY s.subscription_start_date, s.subscription_id
        ) AS previous_plan_name,

        LAG(sp.monthly_price) OVER (
            PARTITION BY s.customer_id
            ORDER BY s.subscription_start_date, s.subscription_id
        ) AS previous_monthly_price

    FROM subscriptions s
    JOIN subscription_plans sp
        ON s.plan_id = sp.plan_id
),

plan_migrations AS (
    SELECT
        customer_id,
        subscription_id,
        subscription_start_date,
        previous_plan_name,
        plan_name AS current_plan_name,

        CASE
            WHEN monthly_price > previous_monthly_price
                THEN 'Upgrade'
            WHEN monthly_price < previous_monthly_price
                THEN 'Downgrade'
            ELSE 'Same price'
        END AS migration_type

    FROM subscription_history
    WHERE previous_plan_id IS NOT NULL
      AND plan_id <> previous_plan_id
),

migration_path_summary AS (
    SELECT
        previous_plan_name || ' → ' || current_plan_name
            AS migration_path,
        migration_type,
        COUNT(*) AS migration_count,
        COUNT(DISTINCT customer_id) AS customer_count
    FROM plan_migrations
    GROUP BY
        previous_plan_name,
        current_plan_name,
        migration_type
),

ranked_migration_paths AS (
    SELECT
        *,
        ROW_NUMBER() OVER (
            ORDER BY migration_count DESC
        ) AS path_rank
    FROM migration_path_summary
),

latest_customer_migration AS (
    SELECT
        customer_id,
        migration_type,

        ROW_NUMBER() OVER (
            PARTITION BY customer_id
            ORDER BY subscription_start_date DESC,
                     subscription_id DESC
        ) AS rn

    FROM plan_migrations
),

churn_comparison AS (
    SELECT
        l.migration_type,
        COUNT(*) AS customer_count,

        COUNT(*) FILTER (
            WHERE cl.churned = TRUE
        ) AS churned_customers,

        ROUND(
            100.0 * COUNT(*) FILTER (
                WHERE cl.churned = TRUE
            ) / NULLIF(COUNT(*), 0),
            2
        ) AS churn_rate_percentage

    FROM latest_customer_migration l
    LEFT JOIN churn_labels cl
        ON l.customer_id = cl.customer_id

    WHERE l.rn = 1
      AND l.migration_type IN ('Upgrade', 'Downgrade')

    GROUP BY l.migration_type
)

SELECT
    'Migration path' AS analysis_type,
    migration_path AS category,
    migration_type,
    migration_count,
    customer_count,
    NULL::BIGINT AS churned_customers,
    NULL::NUMERIC AS churn_rate_percentage,
    path_rank
FROM ranked_migration_paths

UNION ALL

SELECT
    'Churn comparison' AS analysis_type,
    CASE
        WHEN migration_type = 'Upgrade' THEN 'Upgraders'
        ELSE 'Downgraders'
    END AS category,
    migration_type,
    NULL::BIGINT AS migration_count,
    customer_count,
    churned_customers,
    churn_rate_percentage,
    NULL::BIGINT AS path_rank
FROM churn_comparison

ORDER BY
    analysis_type,
    path_rank NULLS LAST,
    category;

--Question-35 Calculate a weekly active user (WAU) and monthly active user (MAU) trend over the last 6 months, and compute the WAU/MAU “stickiness” ratio for each month.

-- Calculate a weekly active user (WAU) and monthly active user (MAU) trend over the last 6 months, and compute the WAU/MAU “stickiness” ratio for each month.

WITH date_bounds AS (
    SELECT
        (DATE_TRUNC('month', MAX(viewing_date)) - INTERVAL '5 months')::DATE AS start_date,
        MAX(viewing_date)::DATE AS end_date
    FROM viewing_activity
),

months AS (
    SELECT
        GENERATE_SERIES(
            start_date,
            DATE_TRUNC('month', end_date)::DATE,
            INTERVAL '1 month'
        )::DATE AS month_start
    FROM date_bounds
),

monthly_active_users AS (
    SELECT
        DATE_TRUNC('month', viewing_date)::DATE AS month_start,
        COUNT(DISTINCT customer_id) AS mau
    FROM viewing_activity
    CROSS JOIN date_bounds
    WHERE viewing_date >= start_date
      AND viewing_date < end_date + INTERVAL '1 day'
    GROUP BY 1
),

weekly_active_users AS (
    SELECT
        DATE_TRUNC('week', viewing_date)::DATE AS week_start,
        COUNT(DISTINCT customer_id) AS wau
    FROM viewing_activity
    CROSS JOIN date_bounds
    WHERE viewing_date >= start_date
      AND viewing_date < end_date + INTERVAL '1 day'
    GROUP BY 1
),

monthly_wau AS (
    SELECT
        DATE_TRUNC('month', week_start)::DATE AS month_start,
        ROUND(AVG(wau), 2) AS average_wau
    FROM weekly_active_users
    GROUP BY 1
)

SELECT
    m.month_start,
    COALESCE(w.average_wau, 0) AS weekly_active_users,
    COALESCE(a.mau, 0) AS monthly_active_users,

    ROUND(
        100.0 * w.average_wau / NULLIF(a.mau, 0),
        2
    ) AS stickiness_ratio_percentage

FROM months m
LEFT JOIN monthly_wau w
    ON m.month_start = w.month_start
LEFT JOIN monthly_active_users a
    ON m.month_start = a.month_start

ORDER BY m.month_start;


-- Question 36: Identify customers who submitted negative feedback
-- within 14 days after a failed payment or low-satisfaction support ticket.

WITH negative_feedback AS (
    SELECT
        feedback_id,
        customer_id,
        feedback_date,
        rating,
        sentiment_label
    FROM customer_feedback
    WHERE feedback_date IS NOT NULL
      AND (
          LOWER(TRIM(sentiment_label)) = 'negative'
          OR rating <= 2
      )
),

failed_payments AS (
    SELECT
        customer_id,
        payment_date
    FROM payments
    WHERE LOWER(TRIM(payment_status)) = 'failed'
      AND payment_date IS NOT NULL
),

low_satisfaction_tickets AS (
    SELECT
        customer_id,
        ticket_date
    FROM support_tickets
    WHERE customer_satisfaction_score <= 2
      AND ticket_date IS NOT NULL
),

-- Match negative feedback with failed payments
payment_matches AS (
    SELECT
        nf.customer_id,
        nf.feedback_id,
        nf.feedback_date,
        'Failed Payment' AS trigger_type
    FROM negative_feedback nf
    JOIN failed_payments fp
        ON nf.customer_id = fp.customer_id
       AND nf.feedback_date BETWEEN fp.payment_date
           AND fp.payment_date + INTERVAL '14 days'
),

-- Match negative feedback with low-satisfaction tickets
ticket_matches AS (
    SELECT
        nf.customer_id,
        nf.feedback_id,
        nf.feedback_date,
        'Low Satisfaction Ticket' AS trigger_type
    FROM negative_feedback nf
    JOIN low_satisfaction_tickets st
        ON nf.customer_id = st.customer_id
       AND nf.feedback_date BETWEEN st.ticket_date
           AND st.ticket_date + INTERVAL '14 days'
),

-- Combine both matching conditions
all_matches AS (
    SELECT * FROM payment_matches

    UNION ALL

    SELECT * FROM ticket_matches
)

-- Final customer outreach list
SELECT
    customer_id,
    COUNT(DISTINCT feedback_id) AS negative_feedback_count,
    COUNT(*) AS matched_trigger_events,
    MIN(feedback_date) AS first_negative_feedback_date,
    MAX(feedback_date) AS latest_negative_feedback_date,
    STRING_AGG(
        DISTINCT trigger_type,
        ', '
    ) AS trigger_types

FROM all_matches
GROUP BY customer_id
ORDER BY negative_feedback_count DESC,
         matched_trigger_events DESC;

-- Question 37 Check the final dataset's date coverage to identify the latest available date in each table before setting the reporting snapshot for Question 37.

SELECT
    'customers' AS table_name,
    'registration_date' AS date_column,
    MIN(registration_date) AS earliest_date,
    MAX(registration_date) AS latest_date,
    COUNT(*) AS total_records,
    COUNT(registration_date) AS non_null_dates
FROM customers

UNION ALL

SELECT
    'viewing_activity',
    'viewing_date',
    MIN(viewing_date),
    MAX(viewing_date),
    COUNT(*),
    COUNT(viewing_date)
FROM viewing_activity

UNION ALL

SELECT
    'payments',
    'payment_date',
    MIN(payment_date),
    MAX(payment_date),
    COUNT(*),
    COUNT(payment_date)
FROM payments

UNION ALL

SELECT
    'support_tickets',
    'ticket_date',
    MIN(ticket_date),
    MAX(ticket_date),
    COUNT(*),
    COUNT(ticket_date)
FROM support_tickets

UNION ALL

SELECT
    'customer_feedback',
    'feedback_date',
    MIN(feedback_date),
    MAX(feedback_date),
    COUNT(*),
    COUNT(feedback_date)
FROM customer_feedback

UNION ALL

SELECT
    'subscriptions',
    'subscription_start_date',
    MIN(subscription_start_date),
    MAX(subscription_start_date),
    COUNT(*),
    COUNT(subscription_start_date)
FROM subscriptions

UNION ALL

SELECT
    'subscriptions',
    'subscription_end_date',
    MIN(subscription_end_date),
    MAX(subscription_end_date),
    COUNT(*),
    COUNT(subscription_end_date)
FROM subscriptions

UNION ALL

SELECT
    'churn_labels',
    'churn_date',
    MIN(churn_date),
    MAX(churn_date),
    COUNT(*),
    COUNT(churn_date)
FROM churn_labels

ORDER BY table_name, date_column;

-- Question-37 updated

-- QUESTION 37: FULL CUSTOMER HEALTH SCORE
-- Reporting snapshot: June 30, 2026

WITH params AS (
    -- Define a fixed reporting date
    SELECT DATE '2026-06-30' AS snapshot_date
),

current_subscriptions AS (
    -- Identify each customer's active subscription
    SELECT
        customer_id,
        plan_name,
        monthly_price
    FROM (
        SELECT
            s.customer_id,
            sp.plan_name,
            COALESCE(s.monthly_price, sp.monthly_price)
                AS monthly_price,

            ROW_NUMBER() OVER (
                PARTITION BY s.customer_id
                ORDER BY
                    s.subscription_start_date DESC,
                    s.subscription_id DESC
            ) AS rn

        FROM subscriptions s

        LEFT JOIN subscription_plans sp
            ON s.plan_id = sp.plan_id

        CROSS JOIN params p

        WHERE LOWER(TRIM(s.subscription_status)) = 'active'
          AND s.subscription_start_date <= p.snapshot_date
          AND (
              s.subscription_end_date IS NULL
              OR s.subscription_end_date >= p.snapshot_date
          )
    ) ranked

    WHERE rn = 1
),

viewing_metrics AS (
    -- Find each customer's latest viewing activity
    SELECT
        va.customer_id,
        MAX(va.viewing_date) AS last_viewing_date

    FROM viewing_activity va
    CROSS JOIN params p

    WHERE va.viewing_date <= p.snapshot_date

    GROUP BY va.customer_id
),

payment_metrics AS (
    -- Calculate payment failure rate
    SELECT
        customer_id,

        COUNT(*) AS total_payments,

        COUNT(*) FILTER (
            WHERE LOWER(TRIM(payment_status)) = 'failed'
        ) AS failed_payments,

        COUNT(*) FILTER (
            WHERE LOWER(TRIM(payment_status)) = 'failed'
        )::NUMERIC
        / NULLIF(COUNT(*), 0) AS payment_failure_rate

    FROM payments
    CROSS JOIN params p

    WHERE payment_date <= p.snapshot_date

    GROUP BY customer_id
),

support_metrics AS (
    -- Calculate average customer support satisfaction
    SELECT
        st.customer_id,

        AVG(st.customer_satisfaction_score::NUMERIC)
            AS avg_support_satisfaction

    FROM support_tickets st
    CROSS JOIN params p

    WHERE st.ticket_date <= p.snapshot_date
      AND st.customer_satisfaction_score IS NOT NULL

    GROUP BY st.customer_id
),

customer_metrics AS (
    -- Combine all customer health indicators
    SELECT
        c.customer_id,

        COALESCE(cs.plan_name, 'No Active Plan')
            AS current_plan,

        cs.monthly_price AS current_monthly_price,

        vm.last_viewing_date,

        CASE
            WHEN vm.last_viewing_date IS NOT NULL
            THEN p.snapshot_date - vm.last_viewing_date
        END AS days_since_last_activity,

        COALESCE(pm.payment_failure_rate, 0)
            AS payment_failure_rate,

        sm.avg_support_satisfaction,

        CASE
            WHEN c.registration_date IS NOT NULL
            THEN p.snapshot_date - c.registration_date
        END AS tenure_days

    FROM customers c

    CROSS JOIN params p

    LEFT JOIN current_subscriptions cs
        ON c.customer_id = cs.customer_id

    LEFT JOIN viewing_metrics vm
        ON c.customer_id = vm.customer_id

    LEFT JOIN payment_metrics pm
        ON c.customer_id = pm.customer_id

    LEFT JOIN support_metrics sm
        ON c.customer_id = sm.customer_id
),

metric_bounds AS (
    -- Calculate minimum and maximum values
    SELECT
        MIN(days_since_last_activity) AS min_recency,
        MAX(days_since_last_activity) AS max_recency,

        MIN(tenure_days) AS min_tenure,
        MAX(tenure_days) AS max_tenure,

        MIN(current_monthly_price) AS min_plan_price,
        MAX(current_monthly_price) AS max_plan_price

    FROM customer_metrics
),

normalized_scores AS (
    -- Normalize each risk indicator to a 0-100 scale
    SELECT
        cm.*,

        -- Recency risk: higher inactivity means higher risk
        CASE
            WHEN days_since_last_activity IS NULL THEN 100
            WHEN mb.max_recency = mb.min_recency THEN 50
            ELSE
                100.0 * (
                    days_since_last_activity - mb.min_recency
                ) / NULLIF(
                    mb.max_recency - mb.min_recency, 0
                )
        END AS recency_risk_score,

        -- Payment risk: higher failure rate means higher risk
        payment_failure_rate * 100
            AS payment_risk_score,

        -- Support risk: lower satisfaction means higher risk
        CASE
            WHEN avg_support_satisfaction IS NULL THEN 50
            ELSE
                ((5.0 - avg_support_satisfaction) / 4.0) * 100
        END AS support_risk_score,

        -- Tenure risk: shorter tenure means higher risk
        CASE
            WHEN tenure_days IS NULL THEN 50
            WHEN mb.max_tenure = mb.min_tenure THEN 50
            ELSE
                100.0 * (
                    mb.max_tenure - tenure_days
                ) / NULLIF(
                    mb.max_tenure - mb.min_tenure, 0
                )
        END AS tenure_risk_score,

        -- Plan risk: lower-priced plans receive higher risk
        CASE
            WHEN current_monthly_price IS NULL THEN 100
            WHEN mb.max_plan_price = mb.min_plan_price THEN 50
            ELSE
                100.0 * (
                    mb.max_plan_price - current_monthly_price
                ) / NULLIF(
                    mb.max_plan_price - mb.min_plan_price, 0
                )
        END AS plan_risk_score

    FROM customer_metrics cm

    CROSS JOIN metric_bounds mb
),

composite_scores AS (
    -- Calculate equally weighted composite risk score
    SELECT
        *,

        ROUND(
            (
                recency_risk_score
                + payment_risk_score
                + support_risk_score
                + tenure_risk_score
                + plan_risk_score
            ) / 5.0,
            2
        ) AS composite_risk_score

    FROM normalized_scores
)

-- Final customer health report
SELECT
    RANK() OVER (
        ORDER BY composite_risk_score DESC
    ) AS risk_rank,

    customer_id,
    current_plan,
    current_monthly_price,
    last_viewing_date,
    days_since_last_activity,

    ROUND(payment_risk_score, 2)
        AS payment_failure_rate_percentage,

    ROUND(avg_support_satisfaction, 2)
        AS average_support_satisfaction,

    tenure_days,

    ROUND(recency_risk_score, 2)
        AS recency_risk_score,

    ROUND(payment_risk_score, 2)
        AS payment_risk_score,

    ROUND(support_risk_score, 2)
        AS support_risk_score,

    ROUND(tenure_risk_score, 2)
        AS tenure_risk_score,

    ROUND(plan_risk_score, 2)
        AS plan_risk_score,

    composite_risk_score

FROM composite_scores

ORDER BY
    composite_risk_score DESC,
    customer_id;



